B.aHA=s(["\u0625\u0646\u0651 \u0633\u064f\u0646\u0651\u0629\u064e \u0627\u0644\u0644\u0647 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0643\u0648\u0646 \u0645\u0627\u0636\u064a\u0629 \u0644\u0627 \u0631\u0627\u062f\u064e\u0651 \u0644\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u0648\u0642\u0641\u0647\u0627 \u0635\u062f\u064c\u0651 \u0623\u0648 \u0639\u0646\u0627\u062f\u060c \u0648\u0644\u0627 \u064a\u064f\u0628\u0637\u0626 \u0645\u0646 \u0645\u0633\u064a\u0631\u062a\u0647\u0627 \u0637\u0648\u0644 \u0627\u0644\u0637\u0631\u064a\u0642 \u0623\u0648 \u0643\u062b\u0631\u0629 \u0627\u0644\u0639\u0648\u0627\u0626\u0642\u060c \u0641\u0627\u0644\u062d\u0642\u064f\u0651 \u062d\u0642\u064c\u0651 \u062d\u062a\u0649 \u0644\u0648 \u0642\u0644\u064e\u0651 \u0623\u0646\u0635\u0627\u0631\u064f\u0647 \u0648\u0643\u062b\u0631\u064e \u062e\u0630\u0644\u0627\u0646 \u0627\u0644\u0646\u0627\u0633\u0650 \u0644\u0647\u060c \u0648\u0631\u063a\u0645 \u0630\u0644\u0643 \u0641\u0625\u0646\u0647 \u064a\u0645\u0636\u064a \u0641\u064a \u0637\u0631\u064a\u0642\u0650\u0647 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u0628\u0627\u0637\u0644\u064f \u0645\u0647\u0645\u0627 \u0628\u0644\u063a\u064e\u062a \u0634\u0631\u0627\u0633\u062a\u064f\u0647\u060c \u0641\u0647\u0648 \u064a\u062a\u0642\u0644\u064e\u0651\u0628\u064f \u0641\u064a \u0639\u062c\u0632\u0650\u0647\u060c \u062d\u062a\u0649 \u0644\u0648 \u0633\u0627\u0646\u062f\u064e\u062a\u0647 \u0643\u0644\u064f\u0651 \u0642\u0648\u0649 \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629.","\u0625\u0646\u0651 \u0627\u0644\u0630\u064a \u064a\u0643\u0641\u0631\u064f \u0628\u0627\u0644\u0644\u0647\u0650 \u0644\u0627 \u064a\u0633\u062a\u0631\u064a\u062d \u0644\u0648\u062c\u0648\u062f \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0630\u0644\u0643 \u0644\u0623\u0646\u0651 \u0646\u0648\u0631 \u0627\u0644\u062d\u0642 \u064a\u064f\u0642\u0644\u0642 \u0639\u064a\u0648\u0646 \u0645\u0646 \u0623\u0644\u0650\u0641\u0648\u0627 \u0627\u0644\u0638\u0644\u0645\u0629\u060c \u0648\u064a\u0643\u0634\u0641 \u0639\u0648\u0631\u0627\u062a \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0648\u064a\u0642\u0648\u0644 \u0627\u0644\u062d\u0642\u064f\u0651 \u0633\u0628\u062d\u0627\u0646\u0647: \ufd3f\u0648\u064e\u064a\u064f\u062d\u0650\u0642\u064f\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0627\u0644\u062d\u064e\u0642\u064e\u0651 \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0648 \u0643\u064e\u0631\u0650\u0647\u064e \u0627\u0644\u0645\u064f\u062c\u0631\u0650\u0645\u064f\u0648\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u064a\u0648\u0646\u0633\u060c \u0641\u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629\u064f \u062a\u062d\u0645\u0644 \u0641\u064a \u0637\u064a\u0651\u0627\u062a\u0650\u0647\u0627 \u0642\u0627\u0646\u0648\u0646\u0627\u064b \u0631\u0628\u0627\u0646\u064a\u0627\u064b \u062b\u0627\u0628\u062a\u0627\u064b\u060c \u0623\u0646 \u0643\u0631\u0627\u0647\u064a\u0629 \u0623\u0647\u0644 \u0627\u0644\u0628\u0627\u0637\u0644 \u0644\u0644\u062d\u0642\u0650\u0651 \u0644\u0627 \u062a\u064f\u0639\u0637\u0650\u0644 \u0645\u0634\u064a\u0626\u0629 \u0627\u0644\u0644\u0647\u0650\u060c \u0641\u0647\u064a \u0646\u0627\u0641\u0630\u0629 \u0641\u0648\u0642 \u0643\u0644\u0650\u0651 \u0625\u0631\u0627\u062f\u0629 \u0648\u0641\u0648\u0642 \u0643\u0644\u0650\u0651 \u0645\u0643\u0631.","\u0648\u0644\u0627 \u0639\u062c\u0628\u064e \u062d\u064a\u0646\u064e \u064a\u0639\u0644\u0648 \u0627\u0644\u0628\u0627\u0637\u0644\u064f \u0648\u062a\u0634\u062a\u062f\u064f\u0651 \u0634\u0631\u0627\u0633\u0629\u064f \u0638\u0644\u0645\u0650\u0647\u060c \u0642\u062f \u062a\u0646\u0642\u0644\u0628\u064f \u0627\u0644\u0645\u0648\u0627\u0632\u064a\u0646\u064f \u0628\u0642\u062f\u0631\u0629\u0650 \u0627\u0644\u0644\u0647\u0650\u060c \u0641\u0645\u0627 \u0643\u0627\u0646\u062a \u062a\u0642\u0648\u0645\u064f \u0628\u0647 \u0642\u0631\u064a\u0634 \u0645\u0646 \u0627\u0644\u0635\u062f\u0650\u0651 \u0639\u0646 \u0633\u0628\u064a\u0644\u0650 \u0627\u0644\u0644\u0647\u0650\u060c \u062a\u062d\u0648\u064e\u0651\u0644\u064e \u0633\u0628\u0628\u0627\u064b \u0641\u064a \u062f\u062e\u0648\u0644\u0650 \u0631\u062c\u0627\u0644\u064d \u0648\u0642\u0628\u0627\u0626\u0644\u064e \u0645\u0646 \u062e\u0627\u0631\u062c\u0650 \u0645\u0643\u0629\u064e \u0641\u064a \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0641\u0643\u0645 \u0645\u0646 \u0642\u0644\u0628\u064d \u0628\u064f\u062b\u064e\u0651\u062a \u0641\u064a\u0647 \u0627\u0644\u0647\u062f\u0627\u064a\u0629\u064f \u0628\u0639\u062f \u0623\u0646 \u0631\u0623\u0649 \u0635\u0627\u062d\u0628\u064f\u0647 \u0645\u0634\u0647\u062f \u062b\u0628\u0627\u062a\u0650 \u0623\u0647\u0644 \u0627\u0644\u062d\u0642\u0650\u0651 \u0623\u0645\u0627\u0645 \u0627\u0644\u0637\u063a\u064a\u0627\u0646\u060c \u0641\u0645\u0627 \u0643\u0627\u0646\u062a \u062a\u062d\u0630\u0631\u064f\u0647 \u0642\u0631\u064a\u0634\u060c \u0623\u064f\u062a\u0650\u064a\u064e\u062a \u0645\u0646\u0647\u060c \u0643\u0645\u0627 \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649:\ufd3f\u0648\u064e\u0646\u064f\u0631\u0650\u064a\u064e \u0641\u0650\u0631\u0639\u064e\u0648\u0646\u064e \u0648\u064e\u0647\u064e\u0627\u0645\u064e\u0627\u0646\u064e \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u0647\u064f\u0645 \u0645\u064e\u0651\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u062d\u0630\u064e\u0631\u064f\u0648\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0642\u0635\u0635"],t.s)
B.Wi=new A.a("B1_C16_T1","\u0648\u064a\u064f\u062d\u0642 \u0627\u0644\u0644\u0647 \u0627\u0644\u062d\u0642 \u0628\u0643\u0644\u0645\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u0644\u0648 \u0643\u064e\u0631\u0650\u0647 \u0627\u0644\u0645\u064f\u062c\u0631\u0645\u0648\u0646",B.aHA)
B.aAw=s(["\u0648\u064e\u0641\u064e\u062f\u064e \u0636\u0650\u0645\u064e\u0627\u062f \u0627\u0644\u0623\u0632\u062f\u064a \u0625\u0644\u0649 \u0645\u0643\u0629\u060c \u0648\u0642\u062f \u0628\u0644\u063a\u0647 \u0645\u0627 \u064a\u064e\u062f\u064e\u0651\u0639\u064a\u0647 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0641\u064a \u062d\u0642 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0646 \u0623\u0646\u0647 \u0645\u062c\u0646\u0648\u0646\u060c \u0648\u0643\u0627\u0646 \u0636\u0650\u0645\u0627\u062f \u0645\u0646 \u0623\u064e\u0632\u062f \u0634\u064e\u0646\u064f\u0648\u0621\u0629 -\u0642\u0628\u064a\u0644\u0629 \u064a\u0645\u0646\u064a\u0629- \u0648\u0643\u0627\u0646 \u064a\u064e\u0631\u0642\u064a \u0627\u0644\u0645\u0635\u0627\u0628\u064a\u0646 \u0628\u0627\u0644\u0631\u064f\u0651\u0642\u064a\u0629 \u0648\u064a\u0639\u0627\u0644\u062c\u0647\u0645\u060c \u0641\u0644\u0645\u0627 \u0633\u0645\u0639 \u0633\u064f\u0641\u0647\u0627\u0621 \u0645\u0643\u0629 \u064a\u0642\u0648\u0644\u0648\u0646 \u0625\u0646 \u0645\u062d\u0645\u062f\u0627\u064b \ufdfa \u0645\u062c\u0646\u0648\u0646\u060c \u0642\u0627\u0644: \u0644\u0648 \u0623\u0646\u064a \u0631\u0623\u064a\u062a \u0647\u0630\u0627 \u0627\u0644\u0631\u062c\u0644 \u0644\u0639\u0644 \u0627\u0644\u0644\u0647 \u064a\u0634\u0641\u064a\u0647 \u0639\u0644\u0649 \u064a\u062f\u064a\u064e\u0651.","\u0641\u0644\u0642\u064a\u0647\u060c \u0648\u0642\u0627\u0644: \u064a\u0627 \u0645\u062d\u0645\u062f\u060c \u0625\u0646\u064a \u0623\u064e\u0631\u0642\u064a \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0631\u064a\u062d -\u064a\u0639\u0646\u064a \u0627\u0644\u062c\u0646\u0648\u0646 \u0648\u0645\u0633\u064e\u0651 \u0627\u0644\u062c\u0646-\u060c \u0648\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0634\u0641\u064a \u0639\u0644\u0649 \u064a\u062f\u064a\u064e\u0651 \u0645\u0646 \u0634\u0627\u0621\u060c \u0641\u0647\u0644 \u0644\u0643\u061f \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \xab\u0625\u0646 \u0627\u0644\u062d\u0645\u062f \u0644\u0644\u0647\u060c \u0646\u062d\u0645\u062f\u0647 \u0648\u0646\u0633\u062a\u0639\u064a\u0646\u0647\u060c \u0648\u0645\u0646 \u064a\u0647\u062f\u0650\u0647 \u0627\u0644\u0644\u0647 \u0641\u0644\u0627 \u0645\u064f\u0636\u0650\u0644\u064e\u0651 \u0644\u0647\u060c \u0648\u0645\u0646 \u064a\u064f\u0636\u0644\u0650\u0644 \u0641\u0644\u0627 \u0647\u0627\u062f\u064a\u064e \u0644\u0647\u060c \u0648\u0623\u0634\u0647\u062f \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0648\u0623\u0646 \u0645\u062d\u0645\u062f\u0627\u064b \u0639\u0628\u062f\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0623\u0645\u0627 \u0628\u0639\u062f\xbb.","\u0641\u0642\u0627\u0644 \u0636\u0650\u0645\u0627\u062f: \u0623\u064e\u0639\u0650\u062f \u0639\u0644\u064a \u0643\u0644\u0645\u0627\u062a\u0643 \u0647\u0624\u0644\u0627\u0621\u060c \u0641\u0623\u0639\u0627\u062f\u0647\u0646 \u0639\u0644\u064a\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062b\u0644\u0627\u062b \u0645\u0631\u0627\u062a\u060c \u062b\u0645 \u0642\u0627\u0644: \u0644\u0642\u062f \u0633\u0645\u0639\u062a \u0642\u0648\u0644 \u0627\u0644\u0643\u0647\u0646\u0629 \u0648\u0642\u0648\u0644 \u0627\u0644\u0633\u062d\u0631\u0629 \u0648\u0642\u0648\u0644 \u0627\u0644\u0634\u0639\u0631\u0627\u0621\u060c \u0641\u0645\u0627 \u0633\u0645\u0639\u062a \u0645\u062b\u0644 \u0643\u0644\u0645\u0627\u062a\u0643 \u0647\u0624\u0644\u0627\u0621\u060c \u0648\u0644\u0642\u062f \u0628\u0644\u063a\u0646 \u0642\u0627\u0645\u0648\u0633 \u0627\u0644\u0628\u062d\u0631 -\u0623\u0639\u0645\u0642 \u0645\u0648\u0636\u0639 \u0641\u064a\u0647-\u060c \u062b\u0645 \u0642\u0627\u0644 \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0647\u0627\u062a \u064a\u062f\u0643 \u0623\u0628\u0627\u064a\u0639\u0643 \u0639\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0641\u0628\u0627\u064a\u0639\u0647\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \xab\u0648\u0639\u0644\u0649 \u0642\u0648\u0645\u0643\xbb\u060c \u0642\u0627\u0644: \u0648\u0639\u0644\u0649 \u0642\u0648\u0645\u064a.","\u0648\u0644\u0645\u0627 \u0642\u0627\u0645\u062a \u062f\u0648\u0644\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u064a \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0628\u064f\u0639\u062b\u062a \u0633\u0631\u0627\u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0645\u0631\u064e\u0651 \u062c\u064a\u0634\u064c \u0639\u0644\u0649 \u0642\u0648\u0645 \u0636\u0650\u0645\u0627\u062f\u060c \u0641\u0633\u0623\u0644 \u0635\u0627\u062d\u0628 \u0627\u0644\u0633\u0631\u064a\u0629 \u062c\u0646\u062f\u0647: \u0647\u0644 \u0623\u0635\u0628\u062a\u0645 \u0645\u0646 \u0647\u0624\u0644\u0627\u0621 \u0634\u064a\u0626\u0627\u064b\u061f \u0641\u0642\u0627\u0644 \u0631\u062c\u0644 \u0645\u0646 \u0627\u0644\u0642\u0648\u0645: \u0623\u0635\u0628\u062a\u064f \u0645\u0646\u0647\u0645 \u0645\u064e\u0637\u0647\u064e\u0631\u0629\u060c \u0641\u0642\u0627\u0644: \u0631\u064f\u062f\u064f\u0651\u0648\u0647\u0627\u060c \u0641\u0625\u0646 \u0647\u0624\u0644\u0627\u0621 \u0642\u0648\u0645 \u0636\u0650\u0645\u0627\u062f."],t.s)
